import{d as c,C as t,o as m,c as b,j as a,a as s,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第十四章","description":"从视听触的限度，读到无状之状，以及执古之道以御今之有。","frontmatter":{"title":"道德经第十四章","description":"从视听触的限度，读到无状之状，以及执古之道以御今之有。","category":"guide","aliases":["道德经第十四章","老子第十四章","dao de jing chapter 14"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-14.md","filePath":"daoism/dao-de-jing/chapter-14.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-14.md"},y=c({...g,setup(p){const n=[{id:"beyond-separate-senses",label:"视之不见，名曰夷",showLabel:!0,sentences:[["视之不见，名曰",{text:"夷",glossary:"yi"},"；听之不闻，名曰",{text:"希",glossary:"xi"},"；"],[{text:"搏",glossary:"bo"},"之不得，名曰",{text:"微",glossary:"wei"},"。"],["此三者不可",{text:"致诘",glossary:"zhijie"},"，故混而为一。"]],note:["【白话】看它却看不见，称作夷；听它却听不到，称作希；伸手把捉却抓不到，称作微。这三方面都不能各自追究成一件确定的东西，因此浑合为一。","【王弼注择要】「无状无象，无声无响。」又说「更以我耳目体不知为名」。夷、希、微是从人的视、听、触不能把握它而立的称谓。","【读法】三者不是三种可以分离测量的材料，也不是道由三块拼成。不可致诘指不能把它按感官对象逐项究定，不是禁止一切追问或讨论。"]},{id:"without-fixed-outline",label:"绳绳不可名",showLabel:!0,sentences:[["其上不",{text:"皦",glossary:"jiao"},"，其下不",{text:"昧",glossary:"mei"},"。"],[{text:"绳绳",glossary:"shengsheng"},"不可名，复归于无物。"]],note:["【白话】它的上面不显得明亮，下面也不显得幽暗；绵延无际，不能用一个确定名称将它圈定，又归于无可指认之物。","【读法】上下与明暗通常帮助我们辨物，这里却不能据以划出它的轮廓。绳绳本页取绵延无际义，读 shéng shéng；不可名不是说所有称谓都毫无作用，而是称谓不能穷尽所指。"]},{id:"form-without-object",label:"无状之状，无物之象",showLabel:!0,sentences:[["是谓无状之状，无物之象，是谓",{text:"惚恍",glossary:"huhuang"},"。"],["迎之不见其首，随之不见其后。"]],note:["【白话】这叫作没有固定形状的形状、并非具体物件的形象，称作惚恍。迎上去看不到它的开头，跟随它也看不到它的末后。","【王弼注择要】「欲言无邪，而物由以成；欲言有邪，而不见其形。」解释惚恍时又说「不可得而定也」。既不能当作一件有形物，也不能以全然无作用概括它。","【读法】无状之状保留一种表达张力：它不供人指认轮廓，却被理解为万物有所由成的根据。首与后同样在撤去可圈定的边界，不是报告看见了某种神秘影像。"]},{id:"ancient-root-and-present-affairs",label:"执古之道，以御今之有",showLabel:!0,sentences:[["执古之道，以",{text:"御",glossary:"yu"},"今之有。"],["能知古始，是谓",{text:"道纪",glossary:"daoji"},"。"]],note:["【白话】把握自古相通的道，用来统理当下的具体事物；能够由此认识古始的根源，就叫作道的纲纪。","【王弼注择要】「有，有其事。」「无形无名者，万物之宗也。」又说「虽今古不同，时移俗易」，说明道虽不成一件有形之物，却关乎古今事务所由成立的根本。","【读法】古之道不等于古代全部制度与风俗。注已承认时移俗易；这里把古始与当下相接，不能据此跳过现实差异，直接照搬旧方法。"]}],r=[{id:"yi",term:"夷",sense:1},{id:"xi",term:"希",sense:1},{id:"bo",term:"搏",sense:1},{id:"wei",term:"微",sense:1},{id:"zhijie",term:"致诘",sense:1},{id:"jiao",term:"皦",sense:1},{id:"mei",term:"昧",sense:1},{id:"shengsheng",term:"绳绳",sense:1,pinyin:"shéng shéng"},{id:"huhuang",term:"惚恍",sense:1},{id:"yu",term:"御",sense:1},{id:"daoji",term:"道纪",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十四章",tabindex:"-1"},[s("道德经第十四章 "),a("a",{class:"header-anchor",href:"#道德经第十四章","aria-label":'Permalink to "道德经第十四章"'},"​")],-1)),o(i,{title:"不能当作一件物，为什么仍能用于当下？",summary:"本章先从视、听、触的限度说起，继而用一连串否定撤去固定轮廓，最后落到古今事务。难点不只在道为何不可见，也在不可见的根本怎样关联具体的有。",points:[{label:"先读",text:"三种感官的不可得，怎样合为同一追问？"},{label:"再辨",text:"无物为什么不等于什么作用都没有？"},{label:"后想",text:"执古之道，怎样同时承认时移俗易？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[s("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),o(l,{sections:n,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第十四章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[s("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"此三者不可致诘，故混而为一。",tone:"合看三名",guide:"夷、希、微分别从感官不能把握处命名，不宜读成三类独立实体。三名将人带向同一个难以对象化的根本。"},{text:"是谓无状之状，无物之象。",tone:"保留张力",guide:"若只抓无，容易读成全然不存在；若只抓状与象，又容易把道想成隐形物件。句式使两边的局限同时显露。"},{text:"执古之道，以御今之有。",tone:"回到事务",guide:"前面的抽象讨论没有停在感官之外，最后回到今之有。理解根本与辨认当下的具体条件，需要一起进行。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[s("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=u('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么连续说不见、不闻、不得" tabindex="-1">象：为什么连续说不见、不闻、不得？ <a class="header-anchor" href="#象-为什么连续说不见、不闻、不得" aria-label="Permalink to &quot;象：为什么连续说不见、不闻、不得？&quot;">​</a></h3><p>通常描述一件东西，会给出颜色、声音、形状和位置。本章反过来说明这些办法怎样不足以圈定道。其目的不是制造一个更加奇异的物件，而是改变读者对根本根据的提问方式。</p><h3 id="理-「无状之状」怎样避免落为空话" tabindex="-1">理：「无状之状」怎样避免落为空话？ <a class="header-anchor" href="#理-「无状之状」怎样避免落为空话" aria-label="Permalink to &quot;理：「无状之状」怎样避免落为空话？&quot;">​</a></h3><p>王弼同时保留两面：物由以成，却不见其形。它在注中承担说明万物所由的角色，不能仅以虚无感替代。我们可以理解其论述结构，也应承认这是一种古代哲学解释，不因文字玄远就宣称它已证明任何具体自然机制。</p><h3 id="用-能从古代根本直接推出今天的办法吗" tabindex="-1">用：能从古代根本直接推出今天的办法吗？ <a class="header-anchor" href="#用-能从古代根本直接推出今天的办法吗" aria-label="Permalink to &quot;用：能从古代根本直接推出今天的办法吗？&quot;">​</a></h3><p>不能省略中间的判断。王弼已承认古今不同、风俗会变；联系今天，需要查明现实对象、条件与后果。根本方向可以帮助追问方法是否合宜，具体方案仍要接受事实与实践的检验。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>分清对象与条件。</strong> 在理解一项活动时，除了找可见的产物，也可以追问它依赖哪些关系与条件。这是从本章获得的提问启发，不宜将任何看不见的组织因素直接称作老子所说的道。</p><p><strong>带着变化读传统。</strong> 借古人观念处理当下问题时，可以先写明借用的原则，再列出古今条件的差别。能够解释何处适用、何处需改，才比单凭一句古语定夺更有帮助。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否曾把一个名称当成了对事物的充分理解？借传统解释当下时，我有哪些尚未核实的前提？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本页保留「皦」「绳绳」「惚恍」及「执古之道」等本站用字，与所据 HFL 录文核对；不混入其他文本的「执今」读法。</li><li>「夷／希／微」依本章视、听、触的语境释义，不机械套用其日常常用义。「绳绳」本页读 shéng shéng，取绵延无际义；现代辞书也见 mǐn mǐn 标音，读音不作为版本异文处理。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，008b–009a</a>；字音参看<a href="https://www.zdic.net/hans/%E7%BB%B3%E7%BB%B3" target="_blank" rel="noreferrer">汉典「绳绳」</a>。</p>',15))])}}});export{_ as __pageData,y as default};
